pred_answer:
A = list(map(int, input().split()))
sorted_A = [1, 2, 3, 4, 5]
diff = [a != b for a, b in zip(A, sorted_A)]
if sum(diff) == 2 and diff.count(True) == 2:
    # Check if swapping the two differing positions would sort the array
    # Find the indices where the difference is True
    idx1 = -1
    idx2 = -1
    for i in range(5):
        if diff[i]:
            if idx1 == -1:
                idx1 = i
            else:
                idx2 = i
    # Swap the elements at idx1 and idx2 and check if it's sorted
    temp = A.copy()
    temp[idx1], temp[idx2] = temp[idx2], temp[idx1]
    if temp == sorted_A:
        print("Yes")
    else:
        print("No")
else:
    print("No")

